// Minimal ZIP writer for the bulk QR download: everything in memory, no ZIP64, no encryption, no streaming.
// The standard library has no archive writer; a package for ~50 lines would be more supply chain than this
// project otherwise carries. Each entry is deflated when that makes it smaller (SVG), stored otherwise (PNG).
const zlib = require('node:zlib');

const MAX_ENTRIES = 0xffff;
const MAX_BYTES = 0xffffffff;

// Names are generated by the server (qr-<slug>.svg); the check is a second line of defence against a
// path that would unpack outside the target folder.
function checkName(name) {
  if (typeof name !== 'string' || !name || Buffer.byteLength(name) > 0xffff
      || name.startsWith('/') || name.includes('\\') || name.split('/').includes('..') || /[\u0000-\u001f]/.test(name)) {
    throw new Error(`invalid zip entry name: ${JSON.stringify(name)}`);
  }
}

// MS-DOS date/time, local time like other ZIP tools. Dates before 1980 clamp to 1980-01-01.
function dosDateTime(d) {
  const year = Math.max(d.getFullYear(), 1980);
  const time = (d.getHours() << 11) | (d.getMinutes() << 5) | (d.getSeconds() >> 1);
  const date = ((year - 1980) << 9) | ((d.getMonth() + 1) << 5) | d.getDate();
  return { time, date };
}

// files: [{ name, data: Buffer|string }]. Returns the finished archive as one Buffer.
function createZip(files, { date = new Date() } = {}) {
  if (files.length > MAX_ENTRIES) throw new Error('too many zip entries');
  const { time, date: day } = dosDateTime(date);
  const locals = [];
  const centrals = [];
  let offset = 0;

  for (const file of files) {
    checkName(file.name);
    const name = Buffer.from(file.name, 'utf8');
    const raw = Buffer.isBuffer(file.data) ? file.data : Buffer.from(file.data, 'utf8');
    const packed = zlib.deflateRawSync(raw);
    const deflated = packed.length < raw.length;
    const body = deflated ? packed : raw;
    const method = deflated ? 8 : 0;
    const crc = zlib.crc32(raw);
    if (raw.length > MAX_BYTES || offset > MAX_BYTES) throw new Error('zip too large');

    const local = Buffer.alloc(30);
    local.writeUInt32LE(0x04034b50, 0);
    local.writeUInt16LE(20, 4); // version needed
    local.writeUInt16LE(0x0800, 6); // flags: names are UTF-8
    local.writeUInt16LE(method, 8);
    local.writeUInt16LE(time, 10);
    local.writeUInt16LE(day, 12);
    local.writeUInt32LE(crc, 14);
    local.writeUInt32LE(body.length, 18);
    local.writeUInt32LE(raw.length, 22);
    local.writeUInt16LE(name.length, 26);
    locals.push(local, name, body);

    const central = Buffer.alloc(46);
    central.writeUInt32LE(0x02014b50, 0);
    central.writeUInt16LE(20, 4); // version made by
    central.writeUInt16LE(20, 6); // version needed
    central.writeUInt16LE(0x0800, 8);
    central.writeUInt16LE(method, 10);
    central.writeUInt16LE(time, 12);
    central.writeUInt16LE(day, 14);
    central.writeUInt32LE(crc, 16);
    central.writeUInt32LE(body.length, 20);
    central.writeUInt32LE(raw.length, 24);
    central.writeUInt16LE(name.length, 28);
    central.writeUInt32LE(offset, 42);
    centrals.push(central, name);

    offset += local.length + name.length + body.length;
  }

  const centralSize = centrals.reduce((n, b) => n + b.length, 0);
  const end = Buffer.alloc(22);
  end.writeUInt32LE(0x06054b50, 0);
  end.writeUInt16LE(files.length, 8);
  end.writeUInt16LE(files.length, 10);
  end.writeUInt32LE(centralSize, 12);
  end.writeUInt32LE(offset, 16);
  return Buffer.concat([...locals, ...centrals, end]);
}

module.exports = { createZip };
